1	//! The `check anchors` subcommand: check a markdown record's
2	//! own links, so a dead anchor is found by a command rather than
3	//! by a reader.
4	//!
5	//! Three checks, all same-file:
6	//!
7	//! - every `](#slug)` link and `[N]: #slug` definition resolves to
8	//!   a heading in the same file
9	//! - every `[[N]]` citation has an `[N]:` definition, and every
10	//!   definition is cited
11	//! - no two headings slug to the same anchor, which markdown
12	//!   silently disambiguates, so the second link lands on the first
13	//!   heading
14	//!
15	//! Cross-file targets (`](other.md#slug)`, `[N]: /notes/x.md#y`)
16	//! are recognized and skipped: resolving one means slugging another
17	//! file's headings, which is its own step (see the `## Todo` entry
18	//! **Reference defs: go file-relative, with anchors**).
19	//!
20	//! Fenced code and code spans are excluded throughout. A `[[N]]` in
21	//! a code span is a quoted identifier rather than a citation, and a
22	//! `#` line inside a fence is code rather than a heading.
23	
24	use std::collections::{BTreeMap, BTreeSet};
25	use std::path::{Path, PathBuf};
26	
27	use clap::Args;
28	use log::{debug, info, trace, warn};
29	
30	use crate::context::Context;
31	use crate::subcommand::SubcommandRunner;
32	
33	/// Clap-derived args for `check anchors`.
34	#[derive(Args, Debug)]
35	pub struct CheckAnchorsArgs {
36	    /// Retired: the files, now `--file` each, refused naming it.
37	    #[arg(value_name = "RETIRED", hide = true)]
38	    pub retired: Vec<String>,
39	
40	    /// A markdown file to check, repeatable. Default: every tracked
41	    /// `.md` in the workspace, excluding the agent repo and build
42	    /// output.
43	    #[arg(long = "file", value_name = "PATH")]
44	    pub files: Vec<PathBuf>,
45	}
46	
47	/// Inputs to the check anchors op, flat, owned, clap-free.
48	pub struct CheckAnchorsParams {
49	    pub files: Vec<PathBuf>,
50	}
51	
52	impl From<&CheckAnchorsArgs> for CheckAnchorsParams {
53	    /// Convert clap-derived args into the flat params (total).
54	    fn from(a: &CheckAnchorsArgs) -> Self {
55	        Self {
56	            files: a.files.clone(),
57	        }
58	    }
59	}
60	
61	impl SubcommandRunner for CheckAnchorsArgs {
62	    type Params = CheckAnchorsParams;
63	
64	    /// Refuse the retired positionals, naming `--file` once per file,
65	    /// else delegate to the `From<&CheckAnchorsArgs>` impl.
66	    fn to_params(&self) -> Result<Self::Params, String> {
67	        if !self.retired.is_empty() {
68	            return Err(crate::options_flags::retired_positional::refusal(
69	                "check anchors",
70	                &self.retired.join(" --file "),
71	                "--file",
72	            ));
73	        }
74	        Ok(CheckAnchorsParams::from(self))
75	    }
76	
77	    /// Run the `check_anchors` op.
78	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
79	        check_anchors(ctx, params)
80	    }
81	}
82	
83	/// One problem found in one file.
84	#[derive(Debug, PartialEq, Eq)]
85	pub struct Finding {
86	    /// 1-based line the problem is on, or 0 when the problem is
87	    /// the file's as a whole (an uncited definition names its own
88	    /// line, so every finding today has one).
89	    pub line: usize,
90	    pub message: String,
91	}
92	
93	/// A heading's GitHub anchor.
94	///
95	/// The algorithm [Markdown anchor
96	/// links](../agent-data/notes.md#markdown-anchor-links) documents:
97	/// lowercase, drop every character that is not alphanumeric, a
98	/// hyphen, or an underscore, and map each remaining space to one
99	/// hyphen. Adjacent spaces are not collapsed, so `a + b` slugs to
100	/// `a--b` while `a: b` slugs to `a-b`.
101	pub fn anchor_slug(heading: &str) -> String {
102	    heading
103	        .chars()
104	        .filter_map(|c| match c {
105	            'a'..='z' | '0'..='9' | '-' | '_' => Some(c),
106	            'A'..='Z' => Some(c.to_ascii_lowercase()),
107	            ' ' => Some('-'),
108	            _ => None,
109	        })
110	        .collect()
111	}
112	
113	/// Blank out code spans in one line, keeping its length so column
114	/// arithmetic still lines up.
115	///
116	/// Backticks pair left to right. An unpaired backtick opens a span
117	/// that runs to the end of the line, which is the reading that
118	/// errs toward ignoring text rather than inventing a citation in
119	/// it.
120	fn blank_code_spans(line: &str) -> String {
121	    let mut out = String::with_capacity(line.len());
122	    let mut in_span = false;
123	    for c in line.chars() {
124	        if c == '`' {
125	            in_span = !in_span;
126	            out.push(' ');
127	        } else if in_span {
128	            out.push(' ');
129	        } else {
130	            out.push(c);
131	        }
132	    }
133	    out
134	}
135	
136	/// The file's lines with fenced blocks and code spans blanked, so
137	/// every later scan sees prose only.
138	fn prose_lines(content: &str) -> Vec<String> {
139	    let mut out = Vec::new();
140	    let mut in_fence = false;
141	    for line in content.lines() {
142	        if line.trim_start().starts_with("```") {
143	            in_fence = !in_fence;
144	            out.push(String::new());
145	            continue;
146	        }
147	        if in_fence {
148	            out.push(String::new());
149	            continue;
150	        }
151	        out.push(blank_code_spans(line));
152	    }
153	    out
154	}
155	
156	/// Collect `(slug, line)` for every heading, in document order.
157	fn headings(lines: &[String]) -> Vec<(String, usize)> {
158	    let mut out = Vec::new();
159	    for (i, line) in lines.iter().enumerate() {
160	        let Some(rest) = line.strip_prefix('#') else {
161	            continue;
162	        };
163	        let text = rest.trim_start_matches('#');
164	        // `#foo` is not a heading, `# foo` is.
165	        if !text.starts_with(' ') {
166	            continue;
167	        }
168	        out.push((anchor_slug(text.trim()), i + 1));
169	    }
170	    out
171	}
172	
173	/// One anchor target found in the prose.
174	struct Target {
175	    slug: String,
176	    line: usize,
177	    /// The file the target names, `None` when it names this one.
178	    /// A named file's slug belongs to that file's headings, which
179	    /// this check does not resolve.
180	    file: Option<String>,
181	}
182	
183	/// Every anchor target naming another file, as `(file, slug, line)`.
184	///
185	/// The check itself resolves none of these. A caller that knows the
186	/// other file can: `config --validate` resolves a config's
187	/// `vc-config.md#<anchor>` links against the schema, since build.rs
188	/// derives those anchors from the key paths.
189	pub fn cross_file_targets(content: &str) -> Vec<(String, String, usize)> {
190	    anchor_targets(&prose_lines(content))
191	        .into_iter()
192	        .filter_map(|t| t.file.map(|f| (f, t.slug, t.line)))
193	        .collect()
194	}
195	
196	/// Every anchor target: `](...#slug)` inline links and
197	/// `[N]: ...#slug` definitions, same-file and cross-file alike.
198	///
199	/// Cross-file ones are collected rather than dropped so the report
200	/// can say how many links it did not resolve, which is exactly the
201	/// coverage this check lacks until the cross-file half lands.
202	fn anchor_targets(lines: &[String]) -> Vec<Target> {
203	    let mut out = Vec::new();
204	    for (i, line) in lines.iter().enumerate() {
205	        for (idx, _) in line.match_indices("](") {
206	            let rest = &line[idx + 2..];
207	            let Some(end) = rest.find(')') else {
208	                continue;
209	            };
210	            let dest = &rest[..end];
211	            if let Some(slug) = dest.strip_prefix('#') {
212	                out.push(Target {
213	                    slug: slug.to_string(),
214	                    line: i + 1,
215	                    file: None,
216	                });
217	            } else if let Some((file, slug)) = dest.split_once('#') {
218	                out.push(Target {
219	                    slug: slug.to_string(),
220	                    line: i + 1,
221	                    file: Some(file.to_string()),
222	                });
223	            }
224	        }
225	        if let Some(rest) = ref_def(line) {
226	            if let Some(slug) = rest.strip_prefix('#') {
227	                out.push(Target {
228	                    slug: slug.trim().to_string(),
229	                    line: i + 1,
230	                    file: None,
231	                });
232	            } else if let Some((file, slug)) = rest.split_once('#') {
233	                out.push(Target {
234	                    slug: slug.trim().to_string(),
235	                    line: i + 1,
236	                    file: Some(file.trim().to_string()),
237	                });
238	            }
239	        }
240	    }
241	    out
242	}
