93	/// A heading's GitHub anchor.
94	///
95	/// The algorithm [Markdown anchor
96	/// links](../agent-data/notes.md#markdown-anchor-links) documents:
97	/// lowercase, drop every character that is not alphanumeric, a
98	/// hyphen, or an underscore, and map each remaining space to one
99	/// hyphen. Adjacent spaces are not collapsed, so `a + b` slugs to
100	/// `a--b` while `a: b` slugs to `a-b`.
101	pub fn anchor_slug(heading: &str) -> String {
102	    heading
103	        .chars()
104	        .filter_map(|c| match c {
105	            'a'..='z' | '0'..='9' | '-' | '_' => Some(c),
106	            'A'..='Z' => Some(c.to_ascii_lowercase()),
107	            ' ' => Some('-'),
108	            _ => None,
109	        })
110	        .collect()
111	}
