114	/// arithmetic still lines up.
115	///
116	/// Backticks pair left to right. An unpaired backtick opens a span
117	/// that runs to the end of the line, which is the reading that
118	/// errs toward ignoring text rather than inventing a citation in
119	/// it.
120	fn blank_code_spans(line: &str) -> String {
121	    let mut out = String::with_capacity(line.len());
122	    let mut in_span = false;
123	    for c in line.chars() {
124	        if c == '`' {
125	            in_span = !in_span;
126	            out.push(' ');
127	        } else if in_span {
128	            out.push(' ');
129	        } else {
130	            out.push(c);
131	        }
132	    }
133	    out
134	}
