183	/// Every anchor target naming another file, as `(file, slug, line)`.
184	///
185	/// The check itself resolves none of these. A caller that knows the
186	/// other file can: `config --validate` resolves a config's
187	/// `vc-config.md#<anchor>` links against the schema, since build.rs
188	/// derives those anchors from the key paths.
189	pub fn cross_file_targets(content: &str) -> Vec<(String, String, usize)> {
190	    anchor_targets(&prose_lines(content))
191	        .into_iter()
192	        .filter_map(|t| t.file.map(|f| (f, t.slug, t.line)))
193	        .collect()
