196	/// Every anchor target: `](...#slug)` inline links and
197	/// `[N]: ...#slug` definitions, same-file and cross-file alike.
198	///
199	/// Cross-file ones are collected rather than dropped so the report
200	/// can say how many links it did not resolve, which is exactly the
201	/// coverage this check lacks until the cross-file half lands.
202	fn anchor_targets(lines: &[String]) -> Vec<Target> {
203	    let mut out = Vec::new();
204	    for (i, line) in lines.iter().enumerate() {
205	        for (idx, _) in line.match_indices("](") {
206	            let rest = &line[idx + 2..];
207	            let Some(end) = rest.find(')') else {
208	                continue;
209	            };
210	            let dest = &rest[..end];
211	            if let Some(slug) = dest.strip_prefix('#') {
212	                out.push(Target {
213	                    slug: slug.to_string(),
214	                    line: i + 1,
215	                    file: None,
216	                });
217	            } else if let Some((file, slug)) = dest.split_once('#') {
218	                out.push(Target {
219	                    slug: slug.to_string(),
220	                    line: i + 1,
221	                    file: Some(file.to_string()),
222	                });
223	            }
224	        }
225	        if let Some(rest) = ref_def(line) {
226	            if let Some(slug) = rest.strip_prefix('#') {
227	                out.push(Target {
228	                    slug: slug.trim().to_string(),
229	                    line: i + 1,
230	                    file: None,
231	                });
232	            } else if let Some((file, slug)) = rest.split_once('#') {
233	                out.push(Target {
234	                    slug: slug.trim().to_string(),
235	                    line: i + 1,
236	                    file: Some(file.trim().to_string()),
237	                });
238	            }
239	        }
240	    }
241	    out
242	}
