278	/// The target of a `[N]: <target>` definition line, if the line is
279	/// one.
280	fn ref_def(line: &str) -> Option<&str> {
281	    let rest = line.trim_start().strip_prefix('[')?;
282	    let (num, rest) = rest.split_once(']')?;
283	    if num.is_empty() || !num.chars().all(|c| c.is_ascii_digit()) {
284	        return None;
285	    }
286	    Some(rest.strip_prefix(':')?.trim())
287	}
288	
289	/// The reference number a `[N]: ...` definition line declares.
290	fn ref_def_number(line: &str) -> Option<u32> {
291	    let rest = line.trim_start().strip_prefix('[')?;
292	    let (num, rest) = rest.split_once(']')?;
293	    rest.strip_prefix(':')?;
294	    num.parse().ok()
295	}
296	
297	/// Every reference number the line uses, in either of the two
298	/// forms that use one.
299	///
300	/// - `[[N]]`, the notes convention's citation, doubled so the
301	///   brackets render.
302	/// - `[text][N]`, a markdown reference link, which is how a ladder
303	///   rung names its own subsection.
304	///
305	/// Both are uses, so a definition either form reaches is cited.
306	fn citations(line: &str) -> Vec<u32> {
307	    let mut out = Vec::new();
308	    for (idx, _) in line.match_indices("[[") {
309	        let rest = &line[idx + 2..];
310	        if let Some(end) = rest.find("]]")
311	            && let Ok(n) = rest[..end].parse::<u32>()
312	        {
313	            out.push(n);
314	        }
315	    }
316	    for (idx, _) in line.match_indices("][") {
317	        let rest = &line[idx + 2..];
318	        if let Some(end) = rest.find(']')
319	            && let Ok(n) = rest[..end].parse::<u32>()
320	        {
321	            out.push(n);
322	        }
323	    }
324	    out
325	}
