327	/// What one file's check looked at, beside what it found.
328	///
329	/// The counts exist so a pass says how much it covered: a file with
330	/// no links passed identically to one with four hundred while the
331	/// summary counted files.
332	#[derive(Debug, Default, PartialEq, Eq)]
333	pub struct Counts {
334	    pub headings: usize,
335	    /// Same-file anchor targets resolved against those headings.
336	    pub anchors_checked: usize,
337	    pub anchors_failed: usize,
338	    /// Targets naming another file, which this check does not
339	    /// resolve. The coverage gap, reported rather than hidden.
340	    pub anchors_cross_file: usize,
341	    pub refs_defined: usize,
342	    pub refs_cited: usize,
343	}
344	
345	/// One thing the check looked at, for `-vv`.
346	#[derive(Debug, PartialEq, Eq)]
347	pub struct Site {
348	    pub line: usize,
349	    pub detail: String,
350	}
351	
352	/// One file's whole result: what was found, what was looked at, and
353	/// how much of each.
354	#[derive(Debug, Default, PartialEq, Eq)]
355	pub struct Report {
356	    pub findings: Vec<Finding>,
357	    pub sites: Vec<Site>,
358	    pub counts: Counts,
359	}
