"""Re-wrap the markdown items that hold a link spanning a line, links and code spans kept whole.

Usage: python3 relink.py FILE...   (rewrites in place, prints the items it re-wrapped per file)
"""
import re
import sys

WIDTH = 100
ITEM = re.compile(r"^(\s*)([-*]|\d+\.) ")


def blank_code(line):
    out, in_span = [], False
    for c in line:
        if c == "`":
            in_span = not in_span
            out.append(" ")
        else:
            out.append(" " if in_span else c)
    return "".join(out)


def began_above(line, idx):
    depth = 0
    for c in reversed(line[:idx]):
        if c == "]":
            depth += 1
        elif c == "[":
            if depth == 0:
                return False
            depth -= 1
    return True


def spans(line):
    b = blank_code(line)
    for m in re.finditer(r"\]\(|\]\[", b):
        if began_above(b, m.start()):
            return True
    return False


def open_state(text):
    """Odd backticks, or a bracket depth above zero outside code: the token is unfinished."""
