1	//! `vc-x1 repo delete`: remove a workspace from this machine.
2	//!
3	//! - The workspace is found by its `.vc-config.md`, as every command
4	//!   finds it: PATH is its root, or the current directory is inside
5	//!   it. A PATH that is not a root is refused, so a path given by
6	//!   hand never reaches a workspace above it.
7	//! - Its parts: the work-repo's directory, the agent-repo's when the
8	//!   config puts it outside the work-repo, and the Claude Code symlink
9	//!   `~/.claude/projects/<encoded root>` when it points at the
10	//!   agent-repo. A symlink pointing elsewhere, or a directory Claude
11	//!   Code made there, is left and named.
12	//! - `--local-repos` adds the bare repos the two `origin`s name when
13	//!   they are paths on this machine. A remote reached by a URL is
14	//!   never touched, and `--local-repos` over one is refused.
15	//! - What is nowhere else stops it: without `--local-repos` the remote
16	//!   keeps what was pushed, so uncommitted work in the work `@` and
17	//!   commits no remote bookmark reaches refuse. With it nothing
18	//!   survives anyway, so they are listed and confirmed. The agent
19	//!   `@` holds the session's data and is listed, never refused.
20	//! - `-s b` names a dual workspace and `-s p` a plain repo, and a scope
21	//!   that does not match the workspace is refused.
22	
23	use std::path::{Path, PathBuf};
24	
25	use clap::{Args, ValueHint};
26	use log::{debug, info};
27	
28	use crate::context::Context;
29	use crate::jj;
30	use crate::options_flags::dry_run::DryRunFlag;
31	use crate::options_flags::scope::{RepoScope, repo_scope_parser};
32	use crate::subcommand::SubcommandRunner;
33	
34	/// Remove a workspace from this machine.
35	#[derive(Args, Debug)]
36	pub struct DeleteArgs {
37	    /// The workspace's root [default: the workspace the current
38	    /// directory is in]
39	    #[arg(value_name = "PATH", value_hint = ValueHint::DirPath)]
40	    pub path: Option<PathBuf>,
41	
42	    /// Also remove the bare repos the `origin`s are, when they are
43	    /// paths on this machine, never a remote reached by a URL
44	    #[arg(long)]
45	    pub local_repos: bool,
46	
47	    /// Remove without asking, for a run with no terminal
48	    #[arg(long)]
49	    pub yes: bool,
50	
51	    /// The workspace's shape, required: `b|both` a dual workspace,
52	    /// `p|por` a plain repo
53	    #[arg(
54	        short = 's',
55	        long,
56	        value_name = "SCOPE",
57	        value_parser = repo_scope_parser(&["both", "por"]),
58	        required = true
59	    )]
60	    pub scope: RepoScope,
61	
62	    /// Print what it would remove, and remove nothing
63	    #[command(flatten)]
64	    pub dry_run: DryRunFlag,
65	}
66	
67	/// Inputs to the delete op, flat, owned, clap-free.
68	#[derive(Debug)]
69	pub struct DeleteParams {
70	    pub path: Option<PathBuf>,
71	    pub local_repos: bool,
72	    pub yes: bool,
73	    pub dual: bool,
74	    pub dry_run: bool,
75	}
76	
77	impl From<&DeleteArgs> for DeleteParams {
78	    fn from(a: &DeleteArgs) -> Self {
79	        DeleteParams {
80	            path: a.path.clone(),
81	            local_repos: a.local_repos,
82	            yes: a.yes,
83	            dual: matches!(a.scope, RepoScope::Sides(_)),
84	            dry_run: a.dry_run.value,
85	        }
86	    }
87	}
88	
89	impl SubcommandRunner for DeleteArgs {
90	    type Params = DeleteParams;
91	
92	    fn to_params(&self) -> Result<Self::Params, String> {
93	        Ok(DeleteParams::from(self))
94	    }
95	
96	    /// Run the `delete` op.
97	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
98	        debug!("repo delete: enter {params:?}");
99	        let cwd = std::env::current_dir()?;
100	        let projects = crate::symlink::default_symlink_dir()?;
101	        delete(ctx, params, &cwd, &projects)
102	    }
103	}
104	
105	/// One repo's `origin`: a bare repo on this machine, a URL, or none.
106	#[derive(Debug, Clone, PartialEq, Eq)]
107	pub enum Origin {
108	    /// No `origin`, as an `init` that failed before publishing leaves.
109	    None,
110	    /// A path on this machine that is a bare git repo.
111	    Local(PathBuf),
112	    /// A path on this machine that is not a bare git repo, never
113	    /// removed, so a config pointing at a working tree is safe.
114	    NotBare(PathBuf),
115	    /// A path on this machine where nothing is, as a run that removed
116	    /// it and stopped leaves.
117	    Gone(PathBuf),
118	    /// A URL, reached over the network, never touched.
119	    Url(String),
120	}
121	
122	/// What is at the Claude Code symlink's path.
123	#[derive(Debug, Clone, PartialEq, Eq)]
124	pub enum Link {
125	    /// Nothing.
126	    Absent,
127	    /// A symlink to the workspace's agent-repo, removed.
128	    Ours(PathBuf),
129	    /// A symlink pointing elsewhere, left.
130	    Elsewhere(PathBuf, PathBuf),
131	    /// Something that is not a symlink, Claude Code's own, left.
132	    NotSymlink(PathBuf),
133	}
134	
135	/// One repo of the workspace and what it holds that is nowhere else.
136	#[derive(Debug, Clone)]
137	pub struct Repo {
138	    /// `work` or the agent-repo's directory name.
139	    pub label: String,
140	    /// The agent-repo, whose `@` is the session's data.
141	    pub agent: bool,
142	    pub path: PathBuf,
143	    /// Removed with its own directory, outside the work-repo.
144	    pub outside: bool,
145	    pub origin: Origin,
146	    /// The working copy holds changes.
147	    pub dirty_at: bool,
148	    /// Commits below `@` no remote bookmark reaches, short ids.
149	    pub unpushed: Vec<String>,
150	}
151	
152	/// Everything `delete` found, before it removes anything.
153	#[derive(Debug, Clone)]
154	pub struct Plan {
155	    pub root: PathBuf,
156	    /// The work-repo first, then the agent-repo of a dual workspace.
157	    pub repos: Vec<Repo>,
158	    pub link: Link,
159	    pub local_repos: bool,
160	}
161	
162	/// The workspace's root: PATH when it is one, else the workspace the
163	/// current directory is in. Refused when there is none, when PATH is
164	/// inside a workspace but not its root, and when the root holds the
165	/// home directory, since removing it would remove the home.
166	pub fn find_root(path: Option<&Path>, cwd: &Path) -> Result<PathBuf, String> {
167	    let root = match path {
168	        Some(p) => {
169	            let p = if p.is_absolute() {
170	                p.to_path_buf()
171	            } else {
172	                cwd.join(p)
173	            };
174	            let p = p
175	                .canonicalize()
176	                .map_err(|e| format!("repo delete: '{}' cannot be read: {e}", p.display()))?;
177	            match crate::common::find_workspace_root_from(&p) {
178	                Some(r) if r == p => r,
179	                Some(r) => {
180	                    return Err(format!(
181	                        "repo delete: '{}' is inside the workspace at '{}', not its root: name the \
182	                         root to delete it",
183	                        p.display(),
184	                        r.display()
185	                    ));
186	                }
187	                None => {
188	                    return Err(format!(
189	                        "repo delete: '{}' is no workspace, having no `.vc-config.md`",
190	                        p.display()
191	                    ));
192	                }
193	            }
194	        }
195	        None => crate::common::find_workspace_root_from(cwd).ok_or_else(|| {
196	            format!(
197	                "repo delete: '{}' is in no workspace, having no `.vc-config.md` above it: name \
198	                 the workspace's root",
199	                cwd.display()
200	            )
201	        })?,
202	    };
203	    if let Some(home) = crate::jj::session::home_dir()
204	        && let Ok(home) = home.canonicalize()
205	        && home.starts_with(&root)
206	    {
207	        return Err(format!(
208	            "repo delete: the workspace at '{}' holds the home directory '{}', and is not removed",
209	            root.display(),
210	            home.display()
211	        ));
212	    }
213	    Ok(root)
214	}
215	
216	/// The local path an `origin` URL names, relative to `repo` when it
217	/// is relative, or `None` when it is a URL reached over the network.
218	pub fn local_path(url: &str, repo: &Path) -> Option<PathBuf> {
219	    let path = url.strip_prefix("file://").unwrap_or(url); // OK: no scheme, the URL is the path
220	    if path.starts_with('/') {
221	        Some(PathBuf::from(path))
222	    } else if path.starts_with("./") || path.starts_with("../") {
223	        Some(repo.join(path))
224	    } else {
225	        None
226	    }
227	}
228	
229	/// Classify `repo`'s `origin`.
230	fn origin_of(repo: &Path) -> Result<Origin, Box<dyn std::error::Error>> {
231	    let Some(url) = jj::remote_url(repo, "origin")? else {
232	        return Ok(Origin::None);
233	    };
234	    let Some(path) = local_path(&url, repo) else {
235	        return Ok(Origin::Url(url));
236	    };
237	    if !path.exists() {
238	        return Ok(Origin::Gone(path));
239	    }
240	    let path = path.canonicalize().unwrap_or(path); // OK: unresolvable, it is named as written
241	    let bare = gix::open(&path).map(|r| r.is_bare()).unwrap_or(false); // OK: unreadable is not bare
242	    Ok(if bare {
243	        Origin::Local(path)
244	    } else {
245	        Origin::NotBare(path)
246	    })
247	}
248	
249	/// Read one repo: its `origin`, its working copy, and the commits
250	/// below `@` no remote bookmark reaches. A directory already gone,
251	/// from a run that stopped, is planned as gone.
252	fn read_repo(
253	    label: &str,
254	    agent: bool,
255	    path: &Path,
256	    outside: bool,
257	) -> Result<Option<Repo>, Box<dyn std::error::Error>> {
258	    if !path.exists() {
259	        return Ok(None);
260	    }
261	    let origin = origin_of(path)?;
262	    let dirty_at = !jj::matches(path, "@ & empty()")?;
263	    let unpushed = jj::cids_short_of(
264	        path,
265	        "::visible_heads() ~ ::remote_bookmarks() ~ root() ~ @",
266	    )?;
267	    Ok(Some(Repo {
268	        label: label.to_string(),
269	        agent,
270	        path: path.to_path_buf(),
271	        outside,
272	        origin,
273	        dirty_at,
274	        unpushed,
275	    }))
276	}
277	
278	/// What is at the symlink's path for the workspace at `root`, in the
279	/// directory `projects`, against the agent-repo `agent`.
280	pub fn link_of(root: &Path, agent: Option<&Path>, projects: &Path) -> Result<Link, String> {
281	    let name = crate::symlink::encode_path(
282	        root.to_str()
283	            .ok_or_else(|| format!("repo delete: '{}' is not valid UTF-8", root.display()))?,
284	    );
285	    let path = projects.join(name);
286	    let Ok(meta) = path.symlink_metadata() else {
287	        return Ok(Link::Absent);
288	    };
289	    if !meta.is_symlink() {
290	        return Ok(Link::NotSymlink(path));
291	    }
292	    let target = std::fs::read_link(&path).map_err(|e| {
293	        format!(
294	            "repo delete: cannot read the symlink '{}': {e}",
295	            path.display()
296	        )
297	    })?;
298	    let resolved = target.canonicalize().unwrap_or_else(|_| target.clone()); // OK: a dangling link compares as written
299	    let ours = agent.is_some_and(|a| a.canonicalize().map(|a| a == resolved).unwrap_or(false)); // OK: an agent-repo gone is not this link's
300	    Ok(if ours {
301	        Link::Ours(path)
302	    } else {
303	        Link::Elsewhere(path, target)
304	    })
305	}
306	
307	/// Find the workspace and plan what `delete` removes, removing
308	/// nothing.
309	pub fn plan(
310	    params: &DeleteParams,
311	    cwd: &Path,
312	    projects: &Path,
313	) -> Result<Plan, Box<dyn std::error::Error>> {
314	    let root = find_root(params.path.as_deref(), cwd)?;
315	    let agent = crate::common::configured_bot_dir(&root)?;
316	    match (params.dual, agent.is_some()) {
317	        (true, false) => {
318	            return Err(format!(
319	                "repo delete -s b: the workspace at '{}' is a plain repo: `-s p` deletes it",
320	                root.display()
321	            )
322	            .into());
323	        }
324	        (false, true) => {
325	            return Err(format!(
326	                "repo delete -s p: the workspace at '{}' is a dual workspace: `-s b` deletes it",
327	                root.display()
328	            )
329	            .into());
330	        }
331	        _ => {}
332	    }
333	    let mut repos: Vec<Repo> = read_repo("work", false, &root, false)?
334	        .into_iter()
335	        .collect();
336	    if let Some(agent) = &agent {
337	        let agent = agent.canonicalize().unwrap_or_else(|_| agent.clone()); // OK: a missing agent-repo is planned as gone
338	        if agent.starts_with(&root) && agent != root {
339	            repos.extend(read_repo(&label_of(&agent), true, &agent, false)?);
340	        } else if agent.starts_with(&root) || root.starts_with(&agent) {
341	            return Err(format!(
342	                "repo delete: the agent-repo '{}' and the work-repo '{}' hold each other, which no \
343	                 workspace vc-x1 makes does: nothing is removed",
344	                agent.display(),
345	                root.display()
346	            )
347	            .into());
348	        } else {
349	            repos.extend(read_repo(&label_of(&agent), true, &agent, true)?);
350	        }
351	    }
352	    let link = link_of(&root, agent.as_deref(), projects)?;
353	    Ok(Plan {
354	        root,
355	        repos,
356	        link,
357	        local_repos: params.local_repos,
358	    })
359	}
360	
361	/// An agent-repo's label, its directory's name.
362	fn label_of(agent: &Path) -> String {
363	    agent
364	        .file_name()
365	        .map(|n| n.to_string_lossy().into_owned())
366	        .unwrap_or_else(|| "agent".to_string()) // OK: a root path has no name
367	}
368	
369	impl Plan {
370	    /// The URL remotes `--local-repos` would have to leave, which
371	    /// refuse it.
372	    pub fn url_remotes(&self) -> Vec<String> {
373	        self.repos
374	            .iter()
375	            .filter_map(|r| match &r.origin {
376	                Origin::Url(u) => Some(format!("{} {u}", r.label)),
377	                _ => None,
378	            })
379	            .collect()
380	    }
381	
382	    /// What is nowhere else, one line each: work in a working copy and
383	    /// commits no remote bookmark reaches. The agent `@` is the
384	    /// session's data and is a note of its own.
385	    pub fn nowhere_else(&self) -> Vec<String> {
386	        let mut out = Vec::new();
387	        for r in &self.repos {
388	            if r.dirty_at && !r.agent {
389	                out.push(format!("{}: @ has uncommitted changes", r.label));
390	            }
391	            if !r.unpushed.is_empty() {
392	                out.push(format!(
393	                    "{}: {} commit(s) no remote bookmark reaches: {}",
394	                    r.label,
395	                    r.unpushed.len(),
396	                    r.unpushed.join(" ")
397	                ));
398	            }
399	        }
400	        out
401	    }
402	
403	    /// Whether the agent `@` holds session data, which goes with it.
404	    pub fn agent_session(&self) -> bool {
405	        self.repos.iter().any(|r| r.agent && r.dirty_at)
406	    }
407	
408	    /// The refusals, each a reason nothing is removed.
409	    pub fn refusals(&self) -> Vec<String> {
410	        let mut out = Vec::new();
411	        if self.local_repos {
412	            for u in self.url_remotes() {
413	                out.push(format!(
414	                    "--local-repos: the origin of {u} is a URL, which delete never touches: \
415	                     run without --local-repos"
416	                ));
417	            }
418	        } else {
419	            for w in self.nowhere_else() {
420	                out.push(format!(
421	                    "{w}, and is nowhere else: push it, or --local-repos to remove it all"
422	                ));
423	            }
424	        }
425	        out
426	    }
427	
428	    /// The lines that say what goes and what stays.
429	    pub fn lines(&self) -> Vec<String> {
430	        let mut out = vec![format!(
431	            "repo delete: the workspace at '{}'",
432	            self.root.display()
433	        )];
434	        match &self.link {
435	            Link::Ours(p) => out.push(format!("  remove the symlink {}", p.display())),
436	            Link::Absent => out.push("  no Claude Code symlink".to_string()),
437	            Link::Elsewhere(p, t) => out.push(format!(
438	                "  leave the symlink {}, pointing at {}, not this workspace",
439	                p.display(),
440	                t.display()
441	            )),
442	            Link::NotSymlink(p) => out.push(format!(
443	                "  leave {}, not a symlink: Claude Code's own",
444	                p.display()
445	            )),
446	        }
447	        for r in &self.repos {
448	            let line = match (&r.origin, self.local_repos) {
449	                (Origin::Local(p), true) => {
450	                    format!("  remove {}'s origin {}", r.label, p.display())
451	                }
452	                (Origin::Local(p), false) => {
453	                    format!(
454	                        "  keep {}'s origin {}, --local-repos removes it",
455	                        r.label,
456	                        p.display()
457	                    )
458	                }
459	                (Origin::NotBare(p), _) => format!(
460	                    "  keep {}'s origin {}, not a bare repo",
461	                    r.label,
462	                    p.display()
463	                ),
464	                (Origin::Url(u), _) => format!("  keep {}'s origin {u}, a URL", r.label),
465	                (Origin::Gone(p), _) => {
466	                    format!("  {}'s origin {} is gone already", r.label, p.display())
467	                }
468	                (Origin::None, _) => format!("  {} has no origin", r.label),
469	            };
470	            out.push(line);
471	        }
472	        for r in self.repos.iter().filter(|r| r.outside) {
473	            out.push(format!(
474	                "  remove the {} repo {}",
475	                r.label,
476	                r.path.display()
477	            ));
478	        }
479	        out.push(format!(
480	            "  remove the work repo {}{}",
481	            self.root.display(),
482	            if self.repos.iter().any(|r| r.agent && !r.outside) {
483	                ", the agent repo inside it"
484	            } else {
485	                ""
486	            }
487	        ));
488	        if self.agent_session() {
489	            out.push("  the agent @ holds session data, which goes with it".to_string());
490	        }
491	        if self.local_repos {
492	            for w in self.nowhere_else() {
493	                out.push(format!("  lost: {w}"));
494	            }
495	        }
496	        out
497	    }
498	}
499	
500	/// Find the workspace, plan, print the plan, and, confirmed, remove
501	/// what it names.
502	pub fn delete(
503	    ctx: &mut Context,
504	    params: &DeleteParams,
505	    cwd: &Path,
506	    projects: &Path,
507	) -> Result<(), Box<dyn std::error::Error>> {
508	    let plan = plan(params, cwd, projects)?;
509	    for line in plan.lines() {
510	        info!("{line}");
511	    }
512	    let refusals = plan.refusals();
513	    if !refusals.is_empty() {
514	        return Err(format!(
515	            "repo delete: nothing is removed:\n  {}",
516	            refusals.join("\n  ")
517	        )
518	        .into());
519	    }
520	    if params.dry_run {
521	        info!("repo delete: [dry-run] nothing is removed");
522	        return Ok(());
523	    }
524	    confirm(params.yes, ctx.stdin_is_tty)?;
525	    remove(&plan)?;
526	    if cwd.starts_with(&plan.root) {
527	        info!("repo delete: done, and this shell's directory is gone with it: `cd` out of it");
528	    } else {
529	        info!("repo delete: done");
530	    }
531	    Ok(())
532	}
533	
534	/// Ask before removing, unless `--yes`. With no terminal to ask, the
535	/// run is refused rather than hung, and a declined answer is an error,
536	/// so a script learns nothing was removed.
537	fn confirm(yes: bool, stdin_is_tty: bool) -> Result<(), Box<dyn std::error::Error>> {
538	    if yes {
539	        debug!("repo delete: --yes, not asked");
540	        return Ok(());
541	    }
542	    if !stdin_is_tty {
543	        return Err(
544	            "repo delete: asking requires a terminal (stdin is not interactive): --yes removes \
545	             without asking, nothing is removed"
546	                .into(),
547	        );
548	    }
549	    let answer = crate::common::prompt("repo delete: remove these? [y/N] ")?;
550	    let answer = answer.trim().to_ascii_lowercase();
551	    if answer != "y" && answer != "yes" {
552	        return Err(format!("repo delete: declined (got {answer:?}), nothing is removed").into());
553	    }
554	    Ok(())
555	}
556	
557	/// Remove the plan's parts in its order: the symlink, so no Claude
558	/// Code session writes into a workspace half gone, the origins under
559	/// `--local-repos`, an agent-repo outside the work-repo, and the
560	/// work-repo last, so a run that stops leaves the workspace findable
561	/// and a second run removes the rest. A failure names what is left.
562	pub fn remove(plan: &Plan) -> Result<(), Box<dyn std::error::Error>> {
563	    // Each step: what it is called, its path, and whether it is the
564	    // symlink, a file, rather than a directory.
565	    let mut steps: Vec<(String, PathBuf, bool)> = Vec::new();
566	    if let Link::Ours(p) = &plan.link {
567	        steps.push((format!("the symlink {}", p.display()), p.clone(), true));
568	    }
569	    if plan.local_repos {
570	        for r in &plan.repos {
571	            if let Origin::Local(p) = &r.origin {
572	                steps.push((
573	                    format!("{}'s origin {}", r.label, p.display()),
574	                    p.clone(),
575	                    false,
576	                ));
577	            }
578	        }
579	    }
580	    for r in plan.repos.iter().filter(|r| r.outside) {
581	        steps.push((
582	            format!("the {} repo {}", r.label, r.path.display()),
583	            r.path.clone(),
584	            false,
585	        ));
586	    }
587	    if plan.root.exists() {
588	        steps.push((
589	            format!("the work repo {}", plan.root.display()),
590	            plan.root.clone(),
591	            false,
592	        ));
593	    }
594	    for (i, (name, path, file)) in steps.iter().enumerate() {
595	        let done = if *file {
596	            std::fs::remove_file(path)
597	        } else {
598	            std::fs::remove_dir_all(path)
599	        };
600	        done.map_err(|e| {
601	            let left: Vec<&str> = steps[i..].iter().map(|(n, _, _)| n.as_str()).collect();
602	            format!(
603	                "repo delete: cannot remove {name}: {e}. Left: {}. A second run removes the rest",
604	                left.join(", ")
605	            )
606	        })?;
607	        info!("repo delete: removed {name}");
608	    }
609	    Ok(())
610	}
611	
612	#[cfg(test)]
613	mod tests {
614	    use super::*;
615	
616	    /// A path is local in its three spellings, and a URL is not.
617	    #[test]
618	    fn an_origin_is_local_when_it_is_a_path() {
619	        let repo = Path::new("/w/ws");
620	        assert_eq!(
621	            local_path("/r/ws.git", repo),
622	            Some(PathBuf::from("/r/ws.git"))
623	        );
624	        assert_eq!(
625	            local_path("file:///r/ws.git", repo),
626	            Some(PathBuf::from("/r/ws.git"))
627	        );
628	        assert_eq!(
629	            local_path("../r/ws.git", repo),
630	            Some(PathBuf::from("/w/ws/../r/ws.git"))
631	        );
632	        assert_eq!(local_path("https://github.com/o/ws.git", repo), None);
633	        assert_eq!(local_path("git@github.com:o/ws.git", repo), None);
634	    }
635	}
