278	/// What is at the symlink's path for the workspace at `root`, in the
279	/// directory `projects`, against the agent-repo `agent`.
280	pub fn link_of(root: &Path, agent: Option<&Path>, projects: &Path) -> Result<Link, String> {
281	    let name = crate::symlink::encode_path(
282	        root.to_str()
283	            .ok_or_else(|| format!("repo delete: '{}' is not valid UTF-8", root.display()))?,
284	    );
285	    let path = projects.join(name);
286	    let Ok(meta) = path.symlink_metadata() else {
287	        return Ok(Link::Absent);
288	    };
289	    if !meta.is_symlink() {
290	        return Ok(Link::NotSymlink(path));
291	    }
292	    let target = std::fs::read_link(&path).map_err(|e| {
293	        format!(
294	            "repo delete: cannot read the symlink '{}': {e}",
295	            path.display()
296	        )
297	    })?;
298	    let resolved = target.canonicalize().unwrap_or_else(|_| target.clone()); // OK: a dangling link compares as written
299	    let ours = agent.is_some_and(|a| a.canonicalize().map(|a| a == resolved).unwrap_or(false)); // OK: an agent-repo gone is not this link's
300	    Ok(if ours {
301	        Link::Ours(path)
302	    } else {
303	        Link::Elsewhere(path, target)
304	    })
305	}
