369	impl Plan {
370	    /// The URL remotes `--local-repos` would have to leave, which
371	    /// refuse it.
372	    pub fn url_remotes(&self) -> Vec<String> {
373	        self.repos
374	            .iter()
375	            .filter_map(|r| match &r.origin {
376	                Origin::Url(u) => Some(format!("{} {u}", r.label)),
377	                _ => None,
378	            })
379	            .collect()
380	    }
