382	    /// What is nowhere else, one line each: work in a working copy and
383	    /// commits no remote bookmark reaches. The agent `@` is the
384	    /// session's data and is a note of its own.
385	    pub fn nowhere_else(&self) -> Vec<String> {
386	        let mut out = Vec::new();
387	        for r in &self.repos {
388	            if r.dirty_at && !r.agent {
389	                out.push(format!("{}: @ has uncommitted changes", r.label));
390	            }
391	            if !r.unpushed.is_empty() {
392	                out.push(format!(
393	                    "{}: {} commit(s) no remote bookmark reaches: {}",
394	                    r.label,
395	                    r.unpushed.len(),
396	                    r.unpushed.join(" ")
397	                ));
398	            }
399	        }
400	        out
401	    }
402	
403	    /// Whether the agent `@` holds session data, which goes with it.
404	    pub fn agent_session(&self) -> bool {
405	        self.repos.iter().any(|r| r.agent && r.dirty_at)
406	    }
407	
408	    /// The refusals, each a reason nothing is removed.
409	    pub fn refusals(&self) -> Vec<String> {
410	        let mut out = Vec::new();
411	        if self.local_repos {
412	            for u in self.url_remotes() {
413	                out.push(format!(
414	                    "--local-repos: the origin of {u} is a URL, which delete never touches: \
415	                     run without --local-repos"
416	                ));
417	            }
418	        } else {
419	            for w in self.nowhere_else() {
420	                out.push(format!(
421	                    "{w}, and is nowhere else: push it, or --local-repos to remove it all"
422	                ));
423	            }
424	        }
425	        out
426	    }
427	
428	    /// The lines that say what goes and what stays.
429	    pub fn lines(&self) -> Vec<String> {
430	        let mut out = vec![format!(
431	            "repo delete: the workspace at '{}'",
432	            self.root.display()
433	        )];
434	        match &self.link {
435	            Link::Ours(p) => out.push(format!("  remove the symlink {}", p.display())),
436	            Link::Absent => out.push("  no Claude Code symlink".to_string()),
437	            Link::Elsewhere(p, t) => out.push(format!(
438	                "  leave the symlink {}, pointing at {}, not this workspace",
439	                p.display(),
440	                t.display()
441	            )),
442	            Link::NotSymlink(p) => out.push(format!(
443	                "  leave {}, not a symlink: Claude Code's own",
444	                p.display()
445	            )),
446	        }
447	        for r in &self.repos {
448	            let line = match (&r.origin, self.local_repos) {
449	                (Origin::Local(p), true) => {
450	                    format!("  remove {}'s origin {}", r.label, p.display())
451	                }
452	                (Origin::Local(p), false) => {
453	                    format!(
454	                        "  keep {}'s origin {}, --local-repos removes it",
455	                        r.label,
456	                        p.display()
457	                    )
458	                }
459	                (Origin::NotBare(p), _) => format!(
460	                    "  keep {}'s origin {}, not a bare repo",
461	                    r.label,
462	                    p.display()
463	                ),
464	                (Origin::Url(u), _) => format!("  keep {}'s origin {u}, a URL", r.label),
465	                (Origin::Gone(p), _) => {
466	                    format!("  {}'s origin {} is gone already", r.label, p.display())
467	                }
468	                (Origin::None, _) => format!("  {} has no origin", r.label),
469	            };
470	            out.push(line);
471	        }
472	        for r in self.repos.iter().filter(|r| r.outside) {
473	            out.push(format!(
474	                "  remove the {} repo {}",
475	                r.label,
476	                r.path.display()
477	            ));
478	        }
479	        out.push(format!(
480	            "  remove the work repo {}{}",
481	            self.root.display(),
482	            if self.repos.iter().any(|r| r.agent && !r.outside) {
483	                ", the agent repo inside it"
484	            } else {
485	                ""
486	            }
487	        ));
488	        if self.agent_session() {
489	            out.push("  the agent @ holds session data, which goes with it".to_string());
490	        }
491	        if self.local_repos {
492	            for w in self.nowhere_else() {
493	                out.push(format!("  lost: {w}"));
494	            }
495	        }
496	        out
497	    }
498	}
