500	/// Find the workspace, plan, print the plan, and, confirmed, remove
501	/// what it names.
502	pub fn delete(
503	    ctx: &mut Context,
504	    params: &DeleteParams,
505	    cwd: &Path,
506	    projects: &Path,
507	) -> Result<(), Box<dyn std::error::Error>> {
508	    let plan = plan(params, cwd, projects)?;
509	    for line in plan.lines() {
510	        info!("{line}");
511	    }
512	    let refusals = plan.refusals();
513	    if !refusals.is_empty() {
514	        return Err(format!(
515	            "repo delete: nothing is removed:\n  {}",
516	            refusals.join("\n  ")
517	        )
518	        .into());
519	    }
520	    if params.dry_run {
521	        info!("repo delete: [dry-run] nothing is removed");
522	        return Ok(());
523	    }
524	    confirm(params.yes, ctx.stdin_is_tty)?;
525	    remove(&plan)?;
526	    if cwd.starts_with(&plan.root) {
527	        info!("repo delete: done, and this shell's directory is gone with it: `cd` out of it");
528	    } else {
529	        info!("repo delete: done");
530	    }
531	    Ok(())
532	}
533	
534	/// Ask before removing, unless `--yes`. With no terminal to ask, the
535	/// run is refused rather than hung, and a declined answer is an error,
536	/// so a script learns nothing was removed.
537	fn confirm(yes: bool, stdin_is_tty: bool) -> Result<(), Box<dyn std::error::Error>> {
538	    if yes {
539	        debug!("repo delete: --yes, not asked");
540	        return Ok(());
541	    }
542	    if !stdin_is_tty {
543	        return Err(
544	            "repo delete: asking requires a terminal (stdin is not interactive): --yes removes \
545	             without asking, nothing is removed"
546	                .into(),
547	        );
548	    }
549	    let answer = crate::common::prompt("repo delete: remove these? [y/N] ")?;
550	    let answer = answer.trim().to_ascii_lowercase();
551	    if answer != "y" && answer != "yes" {
552	        return Err(format!("repo delete: declined (got {answer:?}), nothing is removed").into());
553	    }
554	    Ok(())
555	}
