557	/// Remove the plan's parts in its order: the symlink, so no Claude
558	/// Code session writes into a workspace half gone, the origins under
559	/// `--local-repos`, an agent-repo outside the work-repo, and the
560	/// work-repo last, so a run that stops leaves the workspace findable
561	/// and a second run removes the rest. A failure names what is left.
562	pub fn remove(plan: &Plan) -> Result<(), Box<dyn std::error::Error>> {
563	    // Each step: what it is called, its path, and whether it is the
564	    // symlink, a file, rather than a directory.
565	    let mut steps: Vec<(String, PathBuf, bool)> = Vec::new();
566	    if let Link::Ours(p) = &plan.link {
567	        steps.push((format!("the symlink {}", p.display()), p.clone(), true));
568	    }
569	    if plan.local_repos {
570	        for r in &plan.repos {
571	            if let Origin::Local(p) = &r.origin {
572	                steps.push((
573	                    format!("{}'s origin {}", r.label, p.display()),
574	                    p.clone(),
575	                    false,
576	                ));
577	            }
578	        }
579	    }
580	    for r in plan.repos.iter().filter(|r| r.outside) {
581	        steps.push((
582	            format!("the {} repo {}", r.label, r.path.display()),
583	            r.path.clone(),
584	            false,
585	        ));
586	    }
587	    if plan.root.exists() {
588	        steps.push((
589	            format!("the work repo {}", plan.root.display()),
590	            plan.root.clone(),
591	            false,
592	        ));
593	    }
594	    for (i, (name, path, file)) in steps.iter().enumerate() {
595	        let done = if *file {
596	            std::fs::remove_file(path)
597	        } else {
598	            std::fs::remove_dir_all(path)
599	        };
600	        done.map_err(|e| {
601	            let left: Vec<&str> = steps[i..].iter().map(|(n, _, _)| n.as_str()).collect();
602	            format!(
603	                "repo delete: cannot remove {name}: {e}. Left: {}. A second run removes the rest",
604	                left.join(", ")
605	            )
606	        })?;
607	        info!("repo delete: removed {name}");
608	    }
609	    Ok(())
610	}
