fn edit_config_text(text: &str, key: &str, from: &str, to: &str) -> Option<String> {
    let (table, name) = key.rsplit_once('.')?;
    let mut in_toml = false;
    let mut current = String::new();
    let mut found = false;
    let mut out: Vec<String> = Vec::new();
