    None,
    /// A bare repo on this machine, moved to its new path.
    LocalBare { from: PathBuf, to: PathBuf },
    /// A GitHub repo, renamed there, `owner/name` each.
    GitHub { from: String, to: String },
    /// The name is kept, not being the old one's.

