/// `vc-x1 repo move <args>` from `dir`.
fn relocate(fx: &CliFixture, dir: &Path, args: &[&str]) -> std::process::Command {
    let mut c = fx.cmd();
    c.args(["repo", "move"]).args(args).current_dir(dir);
